/**
 * BOXTIMER PRO — Timer de Boxe Profissional (PWA)
 * - Web Audio API Sintetizada (Campainha/Gongo metálico, Clapper de 10s, Bips de contagem)
 * - Cronômetro de alta precisão sem drift (baseado em performance.now())
 * - Screen Wake Lock API para manter a tela ligada durante o treino
 */

// Áudio Real de Gongo de Boxe (Referência HD: https://www.youtube.com/watch?v=lE5u25nFQ-M)
// Embutido em Base64 para funcionamento 100% offline via Web Audio API (decodeAudioData)
const REAL_SINGLE_BELL_B64 = "";
const REAL_DOUBLE_BELL_B64 = "";

function base64ToArrayBuffer(b64) {
  const bin = atob(b64);
  const len = bin.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = bin.charCodeAt(i);
  }
  return bytes.buffer;
}

class BoxingAudioEngine {
  constructor() {
    this.ctx = null;
    this.compressor = null;
    this.singleBellBuffer = null;
    this.doubleBellBuffer = null;
    this.whistleBuffer = null;
    this.muted = false;
  }

  init() {
    if (!this.ctx) {
      const AudioCtx = window.AudioContext || window.webkitAudioContext;
      if (AudioCtx) {
        this.ctx = new AudioCtx();

        // Compressor / Maximizador de volume para deixar o som alto e estridente no celular
        this.compressor = this.ctx.createDynamicsCompressor();
        this.compressor.threshold.setValueAtTime(-14, this.ctx.currentTime);
        this.compressor.knee.setValueAtTime(6, this.ctx.currentTime);
        this.compressor.ratio.setValueAtTime(12, this.ctx.currentTime);
        this.compressor.attack.setValueAtTime(0.001, this.ctx.currentTime);
        this.compressor.release.setValueAtTime(0.15, this.ctx.currentTime);
        this.compressor.connect(this.ctx.destination);

        // Pré-renderiza os buffers PCM em alta definição (44.1/48kHz)
        this._prepareBuffers();
      }
    }
    if (this.ctx && this.ctx.state === 'suspended') {
      this.ctx.resume();
    }
  }

  _prepareBuffers() {
    if (!this.ctx) return;
    if (!this.whistleBuffer) {
      this.whistleBuffer = this._renderWhistleBuffer();
    }
    if (!this.decodePromise) {
      const decode = (b64) =>
        new Promise((resolve) => {
          const buf = base64ToArrayBuffer(b64);
          this.ctx.decodeAudioData(
            buf,
            (decoded) => resolve(decoded),
            () => resolve(null)
          );
        });
      this.decodePromise = Promise.all([
        decode(REAL_SINGLE_BELL_B64),
        decode(REAL_DOUBLE_BELL_B64)
      ]).then(([singleBuf, doubleBuf]) => {
        this.singleBellBuffer = singleBuf || this._renderBoxingBellBuffer(1);
        this.doubleBellBuffer = doubleBuf || this._renderBoxingBellBuffer(2);
      });
    }
  }

  /**
   * Sintetiza em nível de amostra (PCM Float32) um Gongo/Campainha de Ringue de Aço/Bronze
   * com impacto de martelo metálico, distorção não-linear de tensão (pitch-drop),
   * dezenas de modos inarmônicos estridentes (1kHz–8kHz) e maximização de volume.
   */
  _renderBoxingBellBuffer(strikes = 1) {
    const sr = this.ctx.sampleRate;
    const duration = strikes === 1 ? 2.6 : 2.95;
    const length = Math.floor(sr * duration);
    const buffer = this.ctx.createBuffer(1, length, sr);
    const out = buffer.getChannelData(0);

    // Modos inarmônicos medidos de uma campainha de ringue de boxe de aço/latão de 10"
    // Concentrados na faixa de 1kHz a 7.5kHz para máxima estridência e projeção sonora
    const modes = [
      // Corpo metálico grave/médio
      { f: 628,  a: 0.32, d: 1.10 },
      { f: 964,  a: 0.65, d: 2.10 },
      { f: 971,  a: 0.48, d: 1.95 }, // Batimento com 964Hz
      // Fundamental estridente principal do gongo de boxe
      { f: 1342, a: 1.00, d: 2.40 },
      { f: 1349, a: 0.78, d: 2.25 }, // Batimento metálico rápido (7Hz)
      { f: 1358, a: 0.45, d: 1.85 },
      // Modos superiores penetrantes ("CLANG" de ringue)
      { f: 1876, a: 0.88, d: 1.90 },
      { f: 1887, a: 0.64, d: 1.75 },
      { f: 2465, a: 0.92, d: 1.60 },
      { f: 2479, a: 0.70, d: 1.45 },
      { f: 3118, a: 0.82, d: 1.25 },
      { f: 3136, a: 0.60, d: 1.15 },
      { f: 3845, a: 0.68, d: 0.92 },
      { f: 3869, a: 0.50, d: 0.84 },
      // Brilho metálico agudo e estridência da borda do sino
      { f: 4690, a: 0.55, d: 0.65 },
      { f: 4722, a: 0.40, d: 0.58 },
      { f: 5640, a: 0.42, d: 0.45 },
      { f: 6680, a: 0.32, d: 0.32 },
      { f: 7850, a: 0.24, d: 0.22 }
    ];

    // Tempos de batida: 1 batida (0s) ou 2 batidas rápidas de fim de round (0s e 0.21s)
    const strikeOffsets = strikes === 1 ? [0] : [0, 0.21];

    strikeOffsets.forEach((offsetSec, strikeIdx) => {
      const startSample = Math.floor(offsetSec * sr);
      const phases = modes.map((_, idx) => (idx * 1.37 + strikeIdx * 0.7) % (Math.PI * 2));
      let fmPhase1 = 0;
      let fmPhase2 = 0;

      for (let i = startSample; i < length; i++) {
        const t = (i - startSample) / sr;

        // 1. Deformação elástica do metal no impacto: a frequência começa ~2.4% mais alta
        // nos primeiros 16ms e estabiliza (cria o ataque "K-CLANG!" real de metal batido)
        const pitchBend = 1.0 + 0.024 * Math.exp(-t / 0.015);

        // 2. Modulação FM cruzada de alta frequência no impacto do martelo de aço (primeiros 90ms)
        const fmEnv = Math.exp(-t / 0.045);
        fmPhase1 += (2 * Math.PI * 1793 * pitchBend) / sr;
        fmPhase2 += (2 * Math.PI * 2917 * pitchBend) / sr;
        const fmSignal = (Math.sin(fmPhase1) + 0.7 * Math.sin(fmPhase2)) * fmEnv * 0.85;

        // 3. Soma dos modos de vibração da campainha de aço/latão
        let modalSum = 0;
        for (let m = 0; m < modes.length; m++) {
          const mode = modes[m];
          // Modos mais agudos recebem mais modulação FM no ataque para soar metálico e rasgado
          const fmAmount = m > 5 ? fmSignal * (0.35 + m * 0.05) : fmSignal * 0.15;
          phases[m] += (2 * Math.PI * mode.f * pitchBend) / sr;

          // Envelope de duplo estágio: impacto forte inicial + sustentação brilhante do bronze
          const fastAttack = 0.55 * Math.exp(-t / (mode.d * 0.14));
          const longRing = 0.45 * Math.exp(-t / mode.d);
          const env = fastAttack + longRing;

          modalSum += Math.sin(phases[m] + fmAmount) * mode.a * env;
        }

        // 4. Transiente duplo do martelo de aço (impacto principal em t=0 + micro-repique em t=9ms)
        const hammerHit1 = Math.exp(-t / 0.0045);
        const hammerHit2 = t >= 0.009 ? 0.55 * Math.exp(-(t - 0.009) / 0.0035) : 0;
        const metallicClack =
          (Math.random() * 2 - 1) *
          (hammerHit1 + hammerHit2) *
          (1.8 + Math.sin(t * 2 * Math.PI * 3400));

        // 5. "Sizzle" metálico de alta frequência da vibração da cúpula
        const sizzleEnv = Math.exp(-t / 0.14);
        const sizzle =
          (Math.random() * 2 - 1) *
          Math.sin(phases[6]) *
          Math.sin(phases[10]) *
          sizzleEnv *
          0.9;

        // Se for a 2ª batida no metal já vibrando, atenua levemente o fundo anterior e soma com força
        if (strikeIdx > 0 && t < 0.005) {
          out[i] *= 0.65;
        }

        out[i] += modalSum + metallicClack + sizzle;
      }
    });

    // Normalização + Saturação Harmônica (Overdrive metálico para deixar MUITO alto e cortante)
    let peak = 0.001;
    for (let i = 0; i < length; i++) {
      const abs = Math.abs(out[i]);
      if (abs > peak) peak = abs;
    }
    for (let i = 0; i < length; i++) {
      const normalized = out[i] / peak;
      // Curva tanh empurra o RMS para cima mantendo o timbre agressivo de campainha mecânica
      out[i] = Math.tanh(normalized * 2.5) * 0.98;
    }

    return buffer;
  }

  /**
   * Sintetiza em nível de amostra um Apito Esportivo de Árbitro/Treinador ("Fiu-Fiiiu!")
   * alto e estridente para os 10 segundos finais do round.
   */
  _renderWhistleBuffer() {
    const sr = this.ctx.sampleRate;
    const duration = 0.68;
    const length = Math.floor(sr * duration);
    const buffer = this.ctx.createBuffer(1, length, sr);
    const out = buffer.getChannelData(0);

    // Dois sopros fortes de apito: um curto (0.00s–0.18s) e um longo (0.23s–0.64s)
    const blasts = [
      { start: 0.0, dur: 0.18 },
      { start: 0.23, dur: 0.41 }
    ];

    blasts.forEach((b) => {
      const startSample = Math.floor(b.start * sr);
      const endSample = Math.min(length, Math.floor((b.start + b.dur) * sr));
      let p1 = 0;
      let p2 = 0;
      let p3 = 0;
      let peaPhase = 0;

      for (let i = startSample; i < endSample; i++) {
        const t = (i - startSample) / sr;

        // Envelope de pressão do sopro
        let env = 1.0;
        if (t < 0.015) {
          env = t / 0.015;
        } else if (t > b.dur - 0.035) {
          env = Math.max(0, (b.dur - t) / 0.035);
        }

        // Subida rápida de pressão no início do sopro
        const pitchRise = 1.0 - 0.035 * Math.exp(-t / 0.018);

        // Bolinha de cortiça girando a ~32Hz dentro da câmara do apito (modula tom e volume)
        peaPhase += (2 * Math.PI * 32) / sr;
        const peaTrill = Math.sin(peaPhase);
        const ampMod = 0.78 + 0.22 * peaTrill;
        const freqMod = 1.0 + 0.022 * peaTrill;

        // Duas fendas ressonantes agudas de apito Fox40/Nokona (~2920Hz e ~3110Hz) + 2º harmônico
        const f1 = 2920 * pitchRise * freqMod;
        const f2 = 3110 * pitchRise * freqMod;
        const f3 = 5840 * pitchRise * freqMod;

        p1 += (2 * Math.PI * f1) / sr;
        p2 += (2 * Math.PI * f2) / sr;
        p3 += (2 * Math.PI * f3) / sr;

        const tone =
          0.62 * Math.sin(p1) +
          0.48 * Math.sin(p2) +
          0.18 * Math.sin(p3);

        // Turbulência de ar agudo do apito
        const breath = (Math.random() * 2 - 1) * 0.16 * (0.5 + 0.5 * Math.sin(p1));

        out[i] = Math.tanh((tone * ampMod + breath) * env * 1.9) * 0.96;
      }
    });

    return buffer;
  }

  _playBuffer(buffer, gainValue = 1.35) {
    if (this.muted || !buffer || !this.ctx) return;
    const source = this.ctx.createBufferSource();
    source.buffer = buffer;

    const gainNode = this.ctx.createGain();
    gainNode.gain.setValueAtTime(gainValue, this.ctx.currentTime);

    source.connect(gainNode);
    gainNode.connect(this.compressor || this.ctx.destination);
    source.start(0);
  }

  /**
   * Toca o gongo metálico de boxe:
   * - strikes = 1: 1 batida estridente para INICIAR o round
   * - strikes = 2: 2 batidas rápidas estridentes para ENCERRAR o round
   */
  playGong(strikes = 1) {
    if (this.muted) return;
    this.init();
    if (!this.ctx) return;
    this._prepareBuffers();

    const trigger = () => {
      const targetBuffer = strikes >= 2 ? this.doubleBellBuffer : this.singleBellBuffer;
      if (targetBuffer) {
        // Realça os harmônicos metálicos estridentes (2.8kHz) + ganho alto (1.75x)
        this._playBellBufferWithMetallicBoost(targetBuffer, 1.75);
      }
    };

    if (this.singleBellBuffer && this.doubleBellBuffer) {
      trigger();
    } else if (this.decodePromise) {
      this.decodePromise.then(trigger);
    }
  }

  _playBellBufferWithMetallicBoost(buffer, gainValue = 1.75) {
    if (this.muted || !buffer || !this.ctx) return;
    const source = this.ctx.createBufferSource();
    source.buffer = buffer;

    // Filtro Peaking em 2850Hz (+4.5dB) para ressaltar o timbre metálico estridente do gongo
    const metallicEq = this.ctx.createBiquadFilter();
    metallicEq.type = 'peaking';
    metallicEq.frequency.setValueAtTime(2850, this.ctx.currentTime);
    metallicEq.Q.setValueAtTime(1.1, this.ctx.currentTime);
    metallicEq.gain.setValueAtTime(4.5, this.ctx.currentTime);

    const gainNode = this.ctx.createGain();
    gainNode.gain.setValueAtTime(gainValue, this.ctx.currentTime);

    source.connect(metallicEq);
    metallicEq.connect(gainNode);
    gainNode.connect(this.compressor || this.ctx.destination);
    source.start(0);
  }

  /**
   * Toca o apito esportivo estridente nos últimos 10 segundos do round
   */
  playTenSecondWarning() {
    if (this.muted) return;
    this.init();
    if (!this.ctx) return;
    this._prepareBuffers();

    this._playBuffer(this.whistleBuffer, 1.35);
  }

  /**
   * Bip curto para os últimos 3, 2, 1 segundos
   */
  playCountdownPip(freq = 880) {
    if (this.muted) return;
    this.init();
    if (!this.ctx) return;

    const t = this.ctx.currentTime;
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();

    osc.type = 'sine';
    osc.frequency.setValueAtTime(freq, t);

    gain.gain.setValueAtTime(0.001, t);
    gain.gain.linearRampToValueAtTime(0.38, t + 0.008);
    gain.gain.exponentialRampToValueAtTime(0.001, t + 0.11);

    osc.connect(gain);
    gain.connect(this.ctx.destination);

    osc.start(t);
    osc.stop(t + 0.12);
  }
}

// ============================================================================
// Aplicação Principal do Timer
// ============================================================================

const STORAGE_KEY = 'boxtimer_pro_config_v1';

const DEFAULT_CONFIG = {
  roundSeconds: 180, // 3 minutos
  restSeconds: 60,   // 1 minuto
  totalRounds: 5,    // 5 rounds
  prepSeconds: 5,    // 5s de preparação antes do Round 1
  warnLast10: true   // Aviso sonoro e visual nos 10s finais
};

const THEME_COLORS = {
  'state-idle': '#090b10',
  'state-prep': '#082f49',
  'state-work': '#043927',
  'state-warning': '#78350f',
  'state-rest': '#691212',
  'state-finished': '#172554'
};

class BoxingTimerApp {
  constructor() {
    this.audio = new BoxingAudioEngine();
    this.config = this.loadConfig();
    this.draftConfig = { ...this.config };

    // Estado interno do Timer
    this.phase = 'IDLE'; // IDLE | PREP | WORK | REST | FINISHED
    this.currentRound = 1;
    this.isRunning = false;
    this.phaseDurationMs = this.config.roundSeconds * 1000;
    this.remainingMs = this.phaseDurationMs;
    this.lastFrameTime = 0;
    this.rafId = null;
    this.lastAnnouncedSecond = null;
    this.warnTriggeredThisRound = false;
    this.wakeLock = null;

    this.cacheDOM();
    this.bindEvents();
    this.setupDialogLightDismissFallback();
    this.renderRoundDots();
    this.updateSummaryUI();
    this.syncUI();
  }

  loadConfig() {
    try {
      const saved = localStorage.getItem(STORAGE_KEY);
      if (saved) {
        return { ...DEFAULT_CONFIG, ...JSON.parse(saved) };
      }
    } catch (e) {
      console.warn('Não foi possível ler configurações salvas:', e);
    }
    return { ...DEFAULT_CONFIG };
  }

  saveConfig() {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(this.config));
    } catch (e) {
      console.warn('Não foi possível salvar configurações:', e);
    }
  }

  cacheDOM() {
    this.body = document.body;
    this.themeMeta = document.getElementById('themeColorMeta');
    this.flashOverlay = document.getElementById('flashOverlay');

    this.phaseBadge = document.getElementById('phaseBadge');
    this.roundDisplay = document.getElementById('roundDisplay');
    this.roundDots = document.getElementById('roundDots');
    this.timeDisplay = document.getElementById('timeDisplay');
    this.progressBar = document.getElementById('progressBar');

    this.summaryPill = document.getElementById('summaryPill');
    this.summaryRound = document.getElementById('summaryRound');
    this.summaryRest = document.getElementById('summaryRest');
    this.summaryTotal = document.getElementById('summaryTotal');
    this.summaryWarn = document.getElementById('summaryWarn');
    this.summaryWarnSep = document.getElementById('summaryWarnSep');

    this.startPauseBtn = document.getElementById('startPauseBtn');
    this.startPauseLabel = document.getElementById('startPauseLabel');
    this.playIcon = document.getElementById('playIcon');
    this.pauseIcon = document.getElementById('pauseIcon');
    this.resetBtn = document.getElementById('resetBtn');
    this.skipBtn = document.getElementById('skipBtn');

    this.muteBtn = document.getElementById('muteBtn');
    this.soundOnIcon = document.getElementById('soundOnIcon');
    this.soundOffIcon = document.getElementById('soundOffIcon');

    this.settingsDialog = document.getElementById('settingsDialog');
    this.openSettingsBtn = document.getElementById('openSettingsBtn');
    this.closeSettingsBtn = document.getElementById('closeSettingsBtn');
    this.saveSettingsBtn = document.getElementById('saveSettingsBtn');

    this.cfgRoundValue = document.getElementById('cfgRoundValue');
    this.cfgRestValue = document.getElementById('cfgRestValue');
    this.cfgRoundsValue = document.getElementById('cfgRoundsValue');
    this.cfgPrepValue = document.getElementById('cfgPrepValue');
    this.cfgWarnToggle = document.getElementById('cfgWarnToggle');

    this.testBell1Btn = document.getElementById('testBell1Btn');
    this.testBell2Btn = document.getElementById('testBell2Btn');
    this.testWarnBtn = document.getElementById('testWarnBtn');
    this.presetChips = document.querySelectorAll('.preset-chip');
    this.stepBtns = document.querySelectorAll('.step-btn');
  }

  bindEvents() {
    // Controles Principais
    this.startPauseBtn.addEventListener('click', () => {
      this.audio.init();
      this.toggleStartPause();
    });

    this.resetBtn.addEventListener('click', () => {
      this.audio.init();
      this.resetTimer();
    });

    this.skipBtn.addEventListener('click', () => {
      this.audio.init();
      this.skipPhase();
    });

    // Botão de Mudo
    this.muteBtn.addEventListener('click', () => {
      this.audio.init();
      this.audio.muted = !this.audio.muted;
      this.muteBtn.classList.toggle('is-muted', this.audio.muted);
      this.soundOnIcon.classList.toggle('hidden', this.audio.muted);
      this.soundOffIcon.classList.toggle('hidden', !this.audio.muted);
    });

    // Abrir / Fechar Modal de Configurações
    const openModal = () => {
      this.audio.init();
      if (this.isRunning) {
        this.pauseTimer();
      }
      this.draftConfig = { ...this.config };
      this.syncSettingsModalUI();
      this.settingsDialog.showModal();
    };

    this.openSettingsBtn.addEventListener('click', openModal);
    this.summaryPill.addEventListener('click', openModal);
    this.closeSettingsBtn.addEventListener('click', () => this.settingsDialog.close());

    // Steppers de ajuste (- / +)
    this.stepBtns.forEach((btn) => {
      btn.addEventListener('click', () => {
        const action = btn.dataset.action;
        this.handleStepperAction(action);
      });
    });

    // Presets Rápidos
    this.presetChips.forEach((chip) => {
      chip.addEventListener('click', () => {
        this.draftConfig.roundSeconds = Number(chip.dataset.round);
        this.draftConfig.restSeconds = Number(chip.dataset.rest);
        this.draftConfig.totalRounds = Number(chip.dataset.rounds);
        this.draftConfig.prepSeconds = Number(chip.dataset.prep);
        this.syncSettingsModalUI();
      });
    });

    this.cfgWarnToggle.addEventListener('change', () => {
      this.draftConfig.warnLast10 = this.cfgWarnToggle.checked;
    });

    // Testar Sons no Modal
    this.testBell1Btn.addEventListener('click', () => {
      this.audio.init();
      this.audio.playGong(1);
    });

    this.testBell2Btn.addEventListener('click', () => {
      this.audio.init();
      this.audio.playGong(2);
    });

    this.testWarnBtn.addEventListener('click', () => {
      this.audio.init();
      this.audio.playTenSecondWarning();
    });

    // Salvar Configurações
    this.saveSettingsBtn.addEventListener('click', () => {
      this.config = { ...this.draftConfig };
      this.saveConfig();
      this.settingsDialog.close();
      this.resetTimer();
    });

    // Reativar Wake Lock quando a aba voltar a ficar visível
    document.addEventListener('visibilitychange', () => {
      if (document.visibilityState === 'visible' && this.isRunning) {
        this.requestWakeLock();
      }
    });
  }

  /**
   * Fallback obrigatório para navegadores sem suporte a <dialog closedby="any"> (ex: Safari iOS)
   */
  setupDialogLightDismissFallback() {
    const dialog = this.settingsDialog;
    if (!('closedBy' in HTMLDialogElement.prototype)) {
      dialog.addEventListener('click', (event) => {
        if (event.target !== dialog) return;
        const rect = dialog.getBoundingClientRect();
        const isDialogContent =
          rect.top <= event.clientY &&
          event.clientY <= rect.top + rect.height &&
          rect.left <= event.clientX &&
          event.clientX <= rect.left + rect.width;

        if (isDialogContent) return;
        dialog.close();
      });
    }
  }

  handleStepperAction(action) {
    const c = this.draftConfig;
    switch (action) {
      case 'round-minus':
        c.roundSeconds = Math.max(15, c.roundSeconds - 15);
        break;
      case 'round-plus':
        c.roundSeconds = Math.min(900, c.roundSeconds + 15);
        break;
      case 'rest-minus':
        c.restSeconds = Math.max(10, c.restSeconds - 5);
        break;
      case 'rest-plus':
        c.restSeconds = Math.min(300, c.restSeconds + 5);
        break;
      case 'rounds-minus':
        c.totalRounds = Math.max(1, c.totalRounds - 1);
        break;
      case 'rounds-plus':
        c.totalRounds = Math.min(30, c.totalRounds + 1);
        break;
      case 'prep-minus':
        c.prepSeconds = Math.max(0, c.prepSeconds - 5);
        break;
      case 'prep-plus':
        c.prepSeconds = Math.min(30, c.prepSeconds + 5);
        break;
    }
    this.syncSettingsModalUI();
  }

  syncSettingsModalUI() {
    const c = this.draftConfig;
    this.cfgRoundValue.textContent = this.formatMMSS(c.roundSeconds * 1000);
    this.cfgRestValue.textContent = this.formatMMSS(c.restSeconds * 1000);
    this.cfgRoundsValue.textContent = String(c.totalRounds);
    this.cfgPrepValue.textContent = `${String(c.prepSeconds).padStart(2, '0')}s`;
    this.cfgWarnToggle.checked = Boolean(c.warnLast10);

    this.presetChips.forEach((chip) => {
      const isMatch =
        Number(chip.dataset.round) === c.roundSeconds &&
        Number(chip.dataset.rest) === c.restSeconds &&
        Number(chip.dataset.rounds) === c.totalRounds;
      chip.classList.toggle('active', isMatch);
    });
  }

  // ============================================================================
  // Controle de Estados e Loop de Tempo
  // ============================================================================

  toggleStartPause() {
    if (this.isRunning) {
      this.pauseTimer();
    } else {
      this.startTimer();
    }
  }

  startTimer() {
    if (this.phase === 'FINISHED') {
      this.resetTimer();
    }

    if (this.phase === 'IDLE') {
      if (this.config.prepSeconds > 0) {
        this.enterPhase('PREP', this.config.prepSeconds * 1000);
      } else {
        this.enterPhase('WORK', this.config.roundSeconds * 1000);
      }
    }

    this.isRunning = true;
    this.lastFrameTime = performance.now();
    this.requestWakeLock();
    this.syncUI();
    this.tick();
  }

  pauseTimer() {
    this.isRunning = false;
    if (this.rafId) {
      cancelAnimationFrame(this.rafId);
      this.rafId = null;
    }
    this.releaseWakeLock();
    this.syncUI();
  }

  resetTimer() {
    this.pauseTimer();
    this.phase = 'IDLE';
    this.currentRound = 1;
    this.phaseDurationMs = this.config.roundSeconds * 1000;
    this.remainingMs = this.phaseDurationMs;
    this.lastAnnouncedSecond = null;
    this.warnTriggeredThisRound = false;
    this.renderRoundDots();
    this.updateSummaryUI();
    this.syncUI();
  }

  skipPhase() {
    if (this.phase === 'IDLE') {
      this.enterPhase('WORK', this.config.roundSeconds * 1000);
      this.syncUI();
      return;
    }
    if (this.phase === 'FINISHED') {
      this.resetTimer();
      return;
    }
    this.advanceToNextPhase();
    this.syncUI();
  }

  enterPhase(newPhase, durationMs) {
    this.phase = newPhase;
    this.phaseDurationMs = durationMs;
    this.remainingMs = durationMs;
    this.lastAnnouncedSecond = Math.ceil(durationMs / 1000);
    this.warnTriggeredThisRound = false;

    if (newPhase === 'PREP') {
      this.audio.playCountdownPip(660);
      this.triggerFlash();
    } else if (newPhase === 'WORK') {
      this.audio.playGong(1); // 1 Gongo forte = Início do Round
      this.triggerFlash();
      this.vibrate([250]);
    } else if (newPhase === 'REST') {
      this.audio.playGong(2); // 2 Gongos = Fim do Round / Descanso
      this.triggerFlash();
      this.vibrate([180, 90, 180]);
    } else if (newPhase === 'FINISHED') {
      this.audio.playGong(2); // 2 Batidas de Gongo para encerrar o round final!
      this.triggerFlash();
      this.vibrate([250, 100, 250, 100, 400]);
      this.pauseTimer();
    }

    this.renderRoundDots();
  }

  advanceToNextPhase() {
    if (this.phase === 'PREP') {
      this.enterPhase('WORK', this.config.roundSeconds * 1000);
    } else if (this.phase === 'WORK') {
      if (this.currentRound < this.config.totalRounds) {
        this.enterPhase('REST', this.config.restSeconds * 1000);
      } else {
        this.enterPhase('FINISHED', 0);
      }
    } else if (this.phase === 'REST') {
      this.currentRound += 1;
      this.enterPhase('WORK', this.config.roundSeconds * 1000);
    }
  }

  tick() {
    if (!this.isRunning) return;

    const now = performance.now();
    const delta = now - this.lastFrameTime;
    this.lastFrameTime = now;

    this.remainingMs = Math.max(0, this.remainingMs - delta);
    const currentWholeSecond = Math.ceil(this.remainingMs / 1000);

    // Eventos disparados na virada exata de cada segundo
    if (currentWholeSecond !== this.lastAnnouncedSecond && currentWholeSecond > 0) {
      this.lastAnnouncedSecond = currentWholeSecond;

      // Aviso de últimos 10 segundos do Round
      if (
        this.phase === 'WORK' &&
        this.config.warnLast10 &&
        currentWholeSecond === 10 &&
        !this.warnTriggeredThisRound
      ) {
        this.warnTriggeredThisRound = true;
        this.audio.playTenSecondWarning();
        this.triggerFlash();
        this.vibrate([120, 60, 120]);
      }

      // Bips nos últimos 3, 2, 1 segundos de qualquer fase
      if (currentWholeSecond <= 3 && currentWholeSecond >= 1) {
        this.audio.playCountdownPip(currentWholeSecond === 1 ? 1046.5 : 880);
      }
    }

    this.syncUI();

    if (this.remainingMs <= 0) {
      this.advanceToNextPhase();
      this.syncUI();
    }

    if (this.isRunning) {
      this.rafId = requestAnimationFrame(() => this.tick());
    }
  }

  // ============================================================================
  // Atualização Visual de Alto Contraste
  // ============================================================================

  syncUI() {
    // 1. Definir classe de cor da tela inteira
    const activeStateClass = this.computeBodyStateClass();
    this.body.className = `${activeStateClass}${this.isRunning ? ' is-running' : ''}`;

    // Atualizar cor da barra de status do iOS/Android
    const hexColor = THEME_COLORS[activeStateClass] || '#090b10';
    if (this.themeMeta.getAttribute('content') !== hexColor) {
      this.themeMeta.setAttribute('content', hexColor);
    }

    // 2. Atualizar textos de Fase e Round
    this.roundDisplay.textContent = `ROUND ${this.currentRound} DE ${this.config.totalRounds}`;

    if (this.phase === 'IDLE') {
      this.phaseBadge.textContent = 'PRONTO PARA LUTAR';
    } else if (this.phase === 'PREP') {
      this.phaseBadge.textContent = 'PREPARE-SE';
    } else if (this.phase === 'WORK') {
      const secLeft = Math.ceil(this.remainingMs / 1000);
      if (this.config.warnLast10 && secLeft <= 10) {
        this.phaseBadge.textContent = '⚡ RETA FINAL • 10s ⚡';
      } else {
        this.phaseBadge.textContent = this.isRunning ? '🥊 ROUND ATIVO' : '⏸ ROUND PAUSADO';
      }
    } else if (this.phase === 'REST') {
      this.phaseBadge.textContent = this.isRunning ? '🧊 DESCANSO' : '⏸ DESCANSO PAUSADO';
    } else if (this.phase === 'FINISHED') {
      this.phaseBadge.textContent = '🏆 TREINO CONCLUÍDO!';
    }

    // 3. Atualizar Relógio Gigante
    if (this.phase === 'FINISHED') {
      this.timeDisplay.textContent = 'FIM!';
    } else {
      this.timeDisplay.textContent = this.formatMMSS(this.remainingMs);
    }

    // 4. Atualizar Barra de Progresso
    const ratio =
      this.phaseDurationMs > 0
        ? Math.max(0, Math.min(100, (this.remainingMs / this.phaseDurationMs) * 100))
        : 0;
    this.progressBar.style.width = `${ratio}%`;

    // 5. Atualizar Botão Start / Pause
    if (this.isRunning) {
      this.startPauseLabel.textContent = 'PAUSE';
      this.playIcon.classList.add('hidden');
      this.pauseIcon.classList.remove('hidden');
    } else {
      this.startPauseLabel.textContent =
        this.phase === 'IDLE' || this.phase === 'FINISHED' ? 'START' : 'RETOMAR';
      this.playIcon.classList.remove('hidden');
      this.pauseIcon.classList.add('hidden');
    }
  }

  computeBodyStateClass() {
    if (this.phase === 'IDLE') return 'state-idle';
    if (this.phase === 'PREP') return 'state-prep';
    if (this.phase === 'REST') return 'state-rest';
    if (this.phase === 'FINISHED') return 'state-finished';
    if (this.phase === 'WORK') {
      const secLeft = Math.ceil(this.remainingMs / 1000);
      if (this.config.warnLast10 && secLeft <= 10 && secLeft > 0) {
        return 'state-warning';
      }
      return 'state-work';
    }
    return 'state-idle';
  }

  renderRoundDots() {
    this.roundDots.innerHTML = '';
    const maxDots = Math.min(this.config.totalRounds, 15);
    for (let i = 1; i <= maxDots; i++) {
      const dot = document.createElement('span');
      dot.className = 'round-dot';
      if (i < this.currentRound || this.phase === 'FINISHED') {
        dot.classList.add('done');
      } else if (i === this.currentRound) {
        dot.classList.add('current');
      }
      this.roundDots.appendChild(dot);
    }
  }

  updateSummaryUI() {
    this.summaryRound.textContent = `🥊 ${this.formatMMSS(this.config.roundSeconds * 1000)}`;
    this.summaryRest.textContent = `🧊 ${this.formatMMSS(this.config.restSeconds * 1000)}`;
    this.summaryTotal.textContent = `🔄 ${this.config.totalRounds} ${this.config.totalRounds === 1 ? 'Round' : 'Rounds'}`;
    this.summaryWarn.classList.toggle('hidden', !this.config.warnLast10);
    this.summaryWarnSep.classList.toggle('hidden', !this.config.warnLast10);
  }

  formatMMSS(ms) {
    const totalSeconds = Math.ceil(ms / 1000);
    const minutes = Math.floor(totalSeconds / 60);
    const seconds = totalSeconds % 60;
    return `${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}`;
  }

  triggerFlash() {
    this.flashOverlay.classList.add('active');
    setTimeout(() => {
      this.flashOverlay.classList.remove('active');
    }, 120);
  }

  vibrate(pattern) {
    if ('vibrate' in navigator) {
      try {
        navigator.vibrate(pattern);
      } catch (_) {}
    }
  }

  async requestWakeLock() {
    if ('wakeLock' in navigator) {
      try {
        this.wakeLock = await navigator.wakeLock.request('screen');
      } catch (_) {}
    }
  }

  async releaseWakeLock() {
    if (this.wakeLock) {
      try {
        await this.wakeLock.release();
      } catch (_) {}
      this.wakeLock = null;
    }
  }
}

// Inicialização e Registro do Service Worker (PWA Offline)
window.addEventListener('DOMContentLoaded', () => {
  window.boxTimerApp = new BoxingTimerApp();

  if ('serviceWorker' in navigator) {
    navigator.serviceWorker.register('./sw.js').catch((err) => {
      console.warn('Falha ao registrar Service Worker:', err);
    });
  }
});
